55	int camera_init(void)
56	{
57	  struct v4l2_format fmt;
58	  struct v4l2_requestbuffers req;
59	
60	  g_camera_fd = open(CAMERA_DEV, O_RDWR);
61	  if (g_camera_fd < 0)
62	    {
63	      return FOCUS_ERR_HW_NOTREADY;
64	    }
65	
66	  /* 设置 QVGA RGB565 输出 (匹配驱动实际, RING 模式可采帧) */
67	  memset(&fmt, 0, sizeof(fmt));
68	  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
69	  fmt.fmt.pix.width = CAMERA_WIDTH;
70	  fmt.fmt.pix.height = CAMERA_HEIGHT;
71	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
72	  fmt.fmt.pix.field = V4L2_FIELD_NONE;
73	  if (ioctl(g_camera_fd, VIDIOC_S_FMT, (unsigned long)&fmt) < 0)
74	    {
75	      printf("[camera] S_FMT FAILED errno=%d\n", errno);
76	      close(g_camera_fd);
77	      g_camera_fd = -1;
78	      return FOCUS_ERR_HW_NOTREADY;
79	    }
80	
81	  /* 请求用户指针缓冲区, RING 模式 (驱动循环填充, 设备验证成功) */
82	  memset(&req, 0, sizeof(req));
83	  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
84	  req.memory = V4L2_MEMORY_USERPTR;
85	  req.count = CAMERA_BUFCOUNT;
86	  req.mode  = V4L2_BUF_MODE_RING;
87	  if (ioctl(g_camera_fd, VIDIOC_REQBUFS, (unsigned long)&req) < 0)
88	    {
89	      printf("[camera] REQBUFS FAILED errno=%d\n", errno);
90	      close(g_camera_fd);
91	      g_camera_fd = -1;
92	      return FOCUS_ERR_HW_NOTREADY;
93	    }
94	
95	  /* RING 模式需全部缓冲入队, 分配第 2 缓冲 */
96	  g_cam_buf2 = malloc(CAMERA_BUFSIZE);
97	  if (g_cam_buf2 == NULL)
98	    {
99	      printf("[camera] 第 2 缓冲分配失败\n");
100	      close(g_camera_fd);
101	      g_camera_fd = -1;
102	      return FOCUS_ERR_HW_NOTREADY;
103	    }
104	
105	  return FOCUS_OK;
106	}
