108	/****************************************************************************
109	 * Name: camera_capture_frame
110	 *
111	 * 采一帧 JPEG 到 buf。阻塞上限 500ms。
112	 ****************************************************************************/
113	int camera_capture_frame(uint8_t *buf, size_t *size)
114	{
115	  struct v4l2_buffer vbuf;
116	  struct pollfd pfd;
117	  int type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
118	  int pr;
119	
120	  if (g_camera_fd < 0 || buf == NULL || size == NULL)
121	    {
122	      return FOCUS_ERR_HW_NOTREADY;
123	    }
124	
125	  /* 入队全部缓冲 (RING 模式需环完整, 否则 DQBUF 阻塞) */
126	  {
127	    int i;
128	    for (i = 0; i < CAMERA_BUFCOUNT; i++)
129	      {
130	        memset(&vbuf, 0, sizeof(vbuf));
131	        vbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
132	        vbuf.memory = V4L2_MEMORY_USERPTR;
133	        vbuf.index = i;
134	        vbuf.m.userptr = (unsigned long)((i == 0) ? buf : g_cam_buf2);
135	        vbuf.length = CAMERA_BUFSIZE;
136	        if (ioctl(g_camera_fd, VIDIOC_QBUF, (unsigned long)&vbuf) < 0)
137	          {
138	            return FOCUS_ERR_IO;
139	          }
140	      }
141	  }
142	
143	  /* 开启流 (若已开启会返回 EBUSY, 忽略) */
144	  ioctl(g_camera_fd, VIDIOC_STREAMON, (unsigned long)&type);
145	
146	  /* poll 等待帧可用, 防止驱动异常时 DQBUF 永久阻塞 */
147	  pfd.fd = g_camera_fd;
148	  pfd.events = POLLIN;
149	  pr = poll(&pfd, 1, CAMERA_FRAME_TIMEOUT_MS);
150	  if (pr <= 0)
151	    {
152	      ioctl(g_camera_fd, VIDIOC_STREAMOFF, (unsigned long)&type);
153	      return FOCUS_ERR_TIMEOUT;
154	    }
155	
156	  /* 取一帧 */
157	  memset(&vbuf, 0, sizeof(vbuf));
158	  vbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
159	  vbuf.memory = V4L2_MEMORY_USERPTR;
160	  if (ioctl(g_camera_fd, VIDIOC_DQBUF, (unsigned long)&vbuf) < 0)
161	    {
162	      printf("[camera] DQBUF FAILED errno=%d\n", errno);
163	      ioctl(g_camera_fd, VIDIOC_STREAMOFF, (unsigned long)&type);
164	      return FOCUS_ERR_TIMEOUT;
165	    }
166	
167	  /* 停流复位, 供下一次采集重新 STREAMON (驱动为单帧模式) */
168	  ioctl(g_camera_fd, VIDIOC_STREAMOFF, (unsigned long)&type);
169	
170	  *size = vbuf.bytesused;
171	  camera_frame_buffer = buf;
172	  camera_frame_size   = vbuf.bytesused;
173	
174	  return FOCUS_OK;
175	}
