181	{
182	  if (g_camera_fd >= 0)
183	    {
184	      close(g_camera_fd);
185	      g_camera_fd = -1;
186	    }
187	  if (g_cam_buf2 != NULL)
188	    {
189	      free(g_cam_buf2);
190	      g_cam_buf2 = NULL;
191	    }
192	  camera_frame_buffer = NULL;
193	  camera_frame_size   = 0;
194	}
