786	static void tjei_encode_and_write_MCU(TJEState* state,
787	                                      float* mcu,
788	#if TJE_USE_FAST_DCT
789	                                      float* qt,  // Pre-processed quantization matrix.
790	#else
791	                                      uint8_t* qt,
792	#endif
793	                                      uint8_t* huff_dc_len, uint16_t* huff_dc_code, // Huffman tables
794	                                      uint8_t* huff_ac_len, uint16_t* huff_ac_code,
795	                                      int* pred,  // Previous DC coefficient
796	                                      uint32_t* bitbuffer,  // Bitstack.
797	                                      uint32_t* location)
798	{
799	    int du[64];  // Data unit in zig-zag order
800	
801	    float dct_mcu[64];
802	    memcpy(dct_mcu, mcu, 64 * sizeof(float));
803	
804	#if TJE_USE_FAST_DCT
805	    tjei_fdct(dct_mcu);
806	    for ( int i = 0; i < 64; ++i ) {
807	        float fval = dct_mcu[i];
808	        fval *= qt[i];
809	#if 0
810	        fval = (fval > 0) ? floorf(fval + 0.5f) : ceilf(fval - 0.5f);
811	#else
812	        fval = floorf(fval + 1024 + 0.5f);
813	        fval -= 1024;
814	#endif
815	        int val = (int)fval;
816	        du[tjei_zig_zag[i]] = val;
817	    }
818	#else
819	    for ( int v = 0; v < 8; ++v ) {
820	        for ( int u = 0; u < 8; ++u ) {
821	            dct_mcu[v * 8 + u] = slow_fdct(u, v, mcu);
822	        }
823	    }
824	    for ( int i = 0; i < 64; ++i ) {
825	        float fval = dct_mcu[i] / (qt[i]);
826	        int val = (int)((fval > 0) ? floorf(fval + 0.5f) : ceilf(fval - 0.5f));
827	        du[tjei_zig_zag[i]] = val;
828	    }
829	#endif
830	
831	    uint16_t vli[2];
832	
833	    // Encode DC coefficient.
834	    int diff = du[0] - *pred;
835	    *pred = du[0];
836	    if ( diff != 0 ) {
837	        tjei_calculate_variable_length_int(diff, vli);
838	        // Write number of bits with Huffman coding
839	        tjei_write_bits(state, bitbuffer, location, huff_dc_len[vli[1]], huff_dc_code[vli[1]]);
840	        // Write the bits.
841	        tjei_write_bits(state, bitbuffer, location, vli[1], vli[0]);
842	    } else {
843	        tjei_write_bits(state, bitbuffer, location, huff_dc_len[0], huff_dc_code[0]);
844	    }
845	
846	    // ==== Encode AC coefficients ====
847	
848	    int last_non_zero_i = 0;
849	    // Find the last non-zero element.
850	    for ( int i = 63; i > 0; --i ) {
851	        if (du[i] != 0) {
852	            last_non_zero_i = i;
853	            break;
854	        }
855	    }
856	
857	    for ( int i = 1; i <= last_non_zero_i; ++i ) {
858	        // If zero, increase count. If >=15, encode (FF,00)
859	        int zero_count = 0;
860	        while ( du[i] == 0 ) {
861	            ++zero_count;
862	            ++i;
863	            if (zero_count == 16) {
864	                // encode (ff,00) == 0xf0
865	                tjei_write_bits(state, bitbuffer, location, huff_ac_len[0xf0], huff_ac_code[0xf0]);
866	                zero_count = 0;
867	            }
868	        }
869	        tjei_calculate_variable_length_int(du[i], vli);
870	
871	        assert(zero_count < 0x10);
872	        assert(vli[1] <= 10);
873	
874	        uint16_t sym1 = (uint16_t)((uint16_t)zero_count << 4) | vli[1];
875	
876	        assert(huff_ac_len[sym1] != 0);
877	
878	        // Write symbol 1  --- (RUNLENGTH, SIZE)
879	        tjei_write_bits(state, bitbuffer, location, huff_ac_len[sym1], huff_ac_code[sym1]);
880	        // Write symbol 2  --- (AMPLITUDE)
881	        tjei_write_bits(state, bitbuffer, location, vli[1], vli[0]);
882	    }
883	
884	    if (last_non_zero_i != 63) {
885	        // write EOB HUFF(00,00)
886	        tjei_write_bits(state, bitbuffer, location, huff_ac_len[0], huff_ac_code[0]);
887	    }
888	    return;
889	}

