    size_t i, j = 0;
    for (i = 0; i + 3 <= len; i += 3) {
        uint32_t v = ((uint32_t)src[i]     << 16) |
                     ((uint32_t)src[i + 1] << 8)  |
                      (uint32_t)src[i + 2];
        dst[j++] = tbl[(v >> 18) & 63];
        dst[j++] = tbl[(v >> 12) & 63];
        dst[j++] = tbl[(v >> 6)  & 63];
        dst[j++] = tbl[ v        & 63];
