141	/****************************************************************************
142	 * Name: rgb565_downsample_2x
143	 *
144	 * 2x2 抽样降采样 RGB565 (如 320x240 -> 160x120)。取每 2x2 块的左上角像素,
145	 * 够用且快。用于「设备端不编码、直接把原始帧交给服务器」的方案:
146	 * 全尺寸 320x240 RGB565 base64 后约 205KB, 会压垮 TCP 发送资源
147	 * (send 缓冲仅 16KB, 连接 TIME_WAIT 堆积导致 connect 失败);
148	 * 降到 160x120 后仅约 51KB。
149	 *
150	 * src: 源 RGB565; sw/sh: 源宽高; dst: 目标缓冲 (需 sw/2 * sh/2 * 2 字节)
151	 * 返回: 写入的字节数 (即目标帧大小)
152	 ****************************************************************************/
153	size_t rgb565_downsample_2x(const uint8_t *src, int sw, int sh, uint8_t *dst)
154	{
155	  int dw = sw / 2;
156	  int dh = sh / 2;
157	  int x;
158	  int y;
159	
160	  if (src == NULL || dst == NULL || dw <= 0 || dh <= 0)
161	    {
162	      return 0;
163	    }
164	
165	  for (y = 0; y < dh; y++)
166	    {
167	      for (x = 0; x < dw; x++)
168	        {
169	          size_t si = (((size_t)(y * 2) * sw) + (size_t)(x * 2)) * 2;
170	          size_t di = (((size_t)y * dw) + (size_t)x) * 2;
171	
172	          dst[di]     = src[si];
