  struct timeval tv;
  struct hostent *he;
  int sock;
  int sndbuf = HTTP_SNDBUF_SIZE;

  if (g_http_sock >= 0 && strcmp(g_http_host, host) == 0 &&
      g_http_port == port)
    {
      return g_http_sock;
    }

  http_conn_drop();

  he = gethostbyname(host);
  if (he == NULL)
    {
      return -1;
    }

  sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0)
    {
      return -1;
    }

  tv.tv_sec = HTTP_TIMEOUT_SEC;
  tv.tv_usec = 0;
  if (setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv)) < 0 ||
      setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv)) < 0 ||
      setsockopt(sock, SOL_SOCKET, SO_SNDBUF, &sndbuf, sizeof(sndbuf)) < 0)
    {
      close(sock);
      return -1;
    }

  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_port = htons(port);
  memcpy(&addr.sin_addr, he->h_addr, he->h_length);

  if (connect(sock, (FAR struct sockaddr *)&addr, sizeof(addr)) < 0)
    {
      close(sock);
      return -1;
    }

  g_http_sock = sock;
  snprintf(g_http_host, sizeof(g_http_host), "%s", host);
  g_http_port = port;
  return sock;
}
